"""Implementation of actions for the Register New Patient pane in the XVI application"""

from interops.libraries.squish_actions import CommonActions
from interops.libraries.xvi.interactions.objects.xvi_core_objects import Xvi_MainPage
from interops.libraries.xvi.interactions.objects.xvi_patient_objects import Xvi_Patient_page

def __find_ptient_window() -> bool:
    """Searches for the Patient window of xvi. Returns True if successfully located.

    -> Hidden function that should not be used outside the context of the d_and_i.py file context!

    :return: True or False
    :rtype: bool
    """
    return True if CommonActions.find_object(Xvi_Patient_page.patient_Window) is not None else False

def __find_no_duplicate_patient_dialog() -> bool:
    """Searches for the No Duplicate Patient dialog within the Register Patient workflow. Returns True if successfully located.

    -> Hidden function that should not be used outside the context of the new_patient_reg.py file context!

    :return: True or False
    :rtype: bool
    """
    return True if CommonActions.find_object(Xvi_Patient_page.patient_ID_error_Dialog) is not None else False

def open_patient_newPage() -> bool:
    """Open a new Patient window from main menu
    :return: True or False
    :rtype: bool
    """
    CommonActions.left_click_object(Xvi_MainPage.patient_MenuItem)
    CommonActions.left_click_object(Xvi_Patient_page.patient_New_MenuItem)
    return __find_ptient_window()

def typeText_in_patient_first_name(firstName: str) -> None:
    """Locates the main New Patient Registration window > types a given firstName string into the Demographics first name text box.

    :param str firstName: Patients First Name string to be typed into the first name text box
    """
    if __find_ptient_window():
        CommonActions.type_in_textfield(Xvi_Patient_page.patient_First_Edit, firstName)

