def select_Patients_sex(patientSex: str) -> None:
    """Locates the main New Patient Registration window > selectpatients sex.

    :param str patientSex: select sex
    """
    if __find_ptient_window():
        CommonActions.left_click_object(Xvi_Patient_page.patient_Sex_ComboBox)
        if CommonActions.wait_for_object_exists(Xvi_Patient_page.sex_M_ComboBoxItem):
            if  patientSex=="M":
                CommonActions.left_click_object(Xvi_Patient_page.sex_M_ComboBoxItem)
            elif patientSex=="F":
                CommonActions.left_click_object(Xvi_Patient_page.sex_F_ComboBoxItem)
            else:
                CommonActions.left_click_object(Xvi_Patient_page.sex_O_ComboBoxItem)

