    """Locates the main New Patient Registration window > types a given patient physician Primary string into the Primary text box.

    :param str patientPrimary: Primary string to be typed into the patient patientPhone text box
    """
    if __find_ptient_window():
        child=CommonActions.get_child_objects(Xvi_Patient_page.patient_primary_dropdown)
        CommonActions.type_in_textfield(child[0],patientPrimary)

